// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue) public {
        // Bound burnValue to avoid overflow and ensure it's valid
        vm.assume(burnValue <= 200000000e18); // <= totalDistributed initial

        // First call XBornID() to set initial state
        c.XBornID();

        // Record initial values
        uint256 initTotalSupply = c.totalSupply();
        uint256 initTotalDistributed = c.totalDistributed();
        uint256 initTotalRemaining = c.totalRemaining();

        // Call burn
        c.burn(burnValue);

        // After burn:
        // In reference (P): totalSupply = initTotalSupply - burnValue
        // In mutant (M): totalSupply = initTotalSupply (unchanged)
        uint256 newTotalSupply = c.totalSupply();
        uint256 newTotalDistributed = c.totalDistributed();
        uint256 newTotalRemaining = c.totalRemaining();

        // General rule: newTotalSupply should equal newTotalDistributed + newTotalRemaining + burnValue
        // This holds for P (500000000e18 = (200000000e18 - burnValue) + (300000000e18 + burnValue)? No, let's derive)
        // Actually in both P and M, totalDistributed decreases by burnValue, totalRemaining unchanged.
        // In P: newTotalSupply = initTotalSupply - burnValue.
        // newTotalDistributed + newTotalRemaining = (initTotalDistributed - burnValue) + initTotalRemaining = initTotalDistributed + initTotalRemaining - burnValue = initTotalSupply - burnValue = newTotalSupply.
        // So in P: newTotalSupply = newTotalDistributed + newTotalRemaining.
        // In M: newTotalSupply = initTotalSupply (unchanged), while newTotalDistributed + newTotalRemaining = initTotalSupply - burnValue.
        // So the rule newTotalSupply == newTotalDistributed + newTotalRemaining + burnValue holds for M only.
        // We need a rule that holds for P and fails for M.
        // Rule: newTotalSupply == newTotalDistributed + newTotalRemaining
        assertTrue(newTotalSupply == newTotalDistributed + newTotalRemaining, "totalSupply should equal sum of distributed and remaining");
    }
}

